"""Single original Native episode on a connected straight roadway."""
import argparse, hashlib, json, queue, subprocess, traceback, xml.etree.ElementTree as ET
from pathlib import Path
from worker_exchange.native_output import FrameMap
from worker_exchange.media import compose_four_views
from worker_exchange.world_restore import snapshot, restore

ROOT = Path(__file__).resolve().parent

def check():
    cfg = json.loads((ROOT/'config.json').read_text())
    road = ET.parse(ROOT/'scene.xodr').getroot().find("road[@id='1']")
    assert road is not None and float(road.attrib['length']) >= 1800
    assert len(road.findall('.//lane[@type="driving"]')) >= 2
    assert cfg['duration_s'] == 45 and cfg['rate_hz'] == 20
    assert [c['name'] for c in cfg['cameras']] == ['overview','approach','reference_corner','driver_reference']
    assert [(c['width'],c['height']) for c in cfg['cameras']] == [(1920,1080),(1280,720),(1280,720),(1280,720)]
    assert set(cfg['required_atoms']) == {'kin.speed','kin.velocity','st.one_way_roadway','dev.regulatory_sign'}
    assert len(road.findall('.//lane[@type="driving"]')) == 2 and road.find('.//signal[@type="220"]') is not None
    return {'passed': True, 'road_length_m': float(road.attrib['length']), 'cameras': 4, 'carla_contacted': False}

def run(args):
    import carla
    from pipeline_capture import PipelineCapture
    from analyze import finalize
    client = carla.Client(args.host,args.port); client.set_timeout(60)
    saved = snapshot(client); world = None; owned = []; cameras = {}; queues = {}; encoders = {}; streams = {}; capture = None
    out = Path(args.output_dir); cfg = json.loads((ROOT/'config.json').read_text())
    frames = 0; errors = []
    try:
        world = client.generate_opendrive_world((ROOT/'scene.xodr').read_text())
        settings = world.get_settings(); settings.synchronous_mode=True; settings.fixed_delta_seconds=.05
        world.apply_settings(settings); world.set_weather(carla.WeatherParameters.ClearNoon)
        mapping = world.get_map(); wp = mapping.get_waypoint_xodr(1,-1,10)
        landmarks = mapping.get_all_landmarks()
        if not any(str(getattr(item,'type','')) == '220' for item in landmarks): raise ValueError('Native one-way landmark missing')
        if wp is None: raise ValueError('Native lane 1/-1 is missing')
        blueprint = world.get_blueprint_library().find('vehicle.lincoln.mkz_2020')
        blueprint.set_attribute('role_name','subject_one_way_220_1')
        ego = world.spawn_actor(blueprint, wp.transform); owned.append(ego)
        ego.apply_control(carla.VehicleControl(brake=1,hand_brake=True))
        for _ in range(20): world.tick()
        for spec in cfg['cameras']:
            name,w,h = spec['name'],spec['width'],spec['height']
            bp = world.get_blueprint_library().find('sensor.camera.rgb')
            for key,value in [('image_size_x',w),('image_size_y',h),('fov',spec['fov_deg']),('sensor_tick',0)]:
                bp.set_attribute(key,str(value))
            if name == 'overview': pose = carla.Transform(carla.Location(x=0,y=0,z=80),carla.Rotation(pitch=-90))
            elif name == 'approach': pose = carla.Transform(carla.Location(x=-12,y=0,z=8),carla.Rotation(pitch=-15))
            elif name == 'reference_corner': pose = carla.Transform(carla.Location(x=500,y=-15,z=45),carla.Rotation(pitch=-65))
            else: pose = carla.Transform(carla.Location(x=0,y=0,z=1.5),carla.Rotation())
            camera = world.spawn_actor(bp,pose,attach_to=ego if name in ('overview','approach','driver_reference') else None)
            owned.append(camera); cameras[name]=camera; queues[name]=queue.Queue();camera.listen(queues[name].put)
            stream=(out/(name+'.encoder.log')).open('x');streams[name]=stream
            encoders[name]=subprocess.Popen(['ffmpeg','-nostdin','-hide_banner','-loglevel','error','-n','-f','rawvideo','-pix_fmt','bgra',
                '-s',f'{w}x{h}','-r','20','-i','pipe:0','-an','-c:v','ffv1','-pix_fmt','bgr0',str(out/(name+'.mkv'))],stdin=subprocess.PIPE,stderr=stream)
        capture=PipelineCapture(client,ego,out,cfg['selected_case_id'],required_observations=cfg['required_atoms'])
        started=world.get_snapshot().timestamp.elapsed_seconds
        with FrameMap(out/'video_frames.jsonl') as fmap, (out/'body_history.jsonl').open('x') as body:
            for index in range(cfg['duration_s']*cfg['rate_hz']):
                speed=ego.get_velocity().length(); effort=max(0,min(.6,.3*(cfg['requested_speed_mps']-speed)))
                ego.apply_control(carla.VehicleControl(throttle=effort,brake=max(0,min(.5,.2*(speed-cfg['requested_speed_mps'])))))
                frame=world.tick(); now=world.get_snapshot().timestamp.elapsed_seconds-started
                native_images={}
                for spec in cfg['cameras']:
                    name=spec['name']; image=queues[name].get(timeout=30)
                    while image.frame<frame: image=queues[name].get(timeout=30)
                    if image.frame!=frame: raise ValueError('Camera original tick mismatch: '+name)
                    encoders[name].stdin.write(image.raw_data)
                    native_images[name]={'frame':image.frame,'sha256':hashlib.sha256(image.raw_data).hexdigest()}
                transform=ego.get_transform(); vertices=[[v.x,v.y,v.z] for v in ego.bounding_box.get_world_vertices(transform)]
                body.write(json.dumps({'frame':frame,'time_s':now,'vertices_m':vertices,'camera_originals':native_images})+'\n')
                capture.capture(frame,now)
                fmap.append(frame,now)
                frames+=1
        if frames!=cfg['duration_s']*cfg['rate_hz']: raise ValueError('Incomplete original duration')
    except BaseException as error:
        errors.append({'message':str(error),'traceback':traceback.format_exc()})
    finally:
        if capture:
            try: capture.close(confirmed=not errors and frames==cfg['duration_s']*cfg['rate_hz'])
            except BaseException as error: errors.append({'capture_close':str(error)})
        for process in encoders.values():
            try:
                process.stdin.close()
                if process.wait(timeout=180): errors.append({'encoder_exit':process.returncode})
            except BaseException as error: errors.append({'encoder':str(error)})
        for stream in streams.values(): stream.close()
        for actor in reversed(owned):
            try: actor.destroy()
            except BaseException as error: errors.append({'destroy':str(error)})
        try: restoration=restore(client,saved)
        except BaseException as error: errors.append({'restore':str(error)}); restoration={'restored':False}
        (out/'native-run-status.json').write_text(json.dumps({'frames':frames,'errors':errors,'restoration':restoration},indent=2)+'\n')
    if errors: raise RuntimeError('Native capture failed: '+str(errors))
    sources={name:out/(name+'.mkv') for name in cameras}
    receipt=compose_four_views(sources,out/'video_frames.jsonl',out/'raw.mkv')
    (out/'four-view-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
    context={'designation_source':'authored synthetic public highway for this test; legal public-way status unresolved',
             'road_geometry_source':'scene.xodr, Native generated map and road.xodr',
             'road_id':1,'native_map_name':mapping.name,'motion_source':'original Native actor velocity'}
    (out/'alley_context.json').write_text(json.dumps(context,indent=2)+'\n')
    rows=[json.loads(line) for line in (out/'trace.jsonl').read_text().splitlines() if line]
    mapping_rows=[json.loads(line) for line in (out/'video_frames.jsonl').read_text().splitlines() if line]
    sign={'native_id':220001,'text':'ONE WAY','orientation_deg':0,'governs_roadway_indices':[0],
          'original_frames':[row['carla_frame'] for row in mapping_rows], 'pixel_visibility_verified':False}
    obs={'law_id':cfg['law_id'],'diagnostic_fixture_only':False,'direction_sign':sign,'one_way_lanes':[-1,-2],
         'designated_direction_xy':[1,0],
         'velocity_rows':[{'frame':row['frame'],'velocity_xy':row['velocity_mps'][:2]} for row in rows]}
    (out/'case_observation.json').write_text(json.dumps(obs,indent=2)+'\n')
    geometry={'source':'authored scene.xodr and Native map landmark survey','physical_verification':{'native_landmark_ids':[str(x.id) for x in landmarks],
      'source_road':'road.xodr','original_frame_map':'video_frames.jsonl','sign_pixels_verified':False},
      'directed_roadways':[{'polygon':[[0,-8.5],[1800,-8.5],[1800,0],[0,0]],'direction_xy':[1,0],'one_way':True}],
      'direction_sign_objects':[{'id':220001,'native_name':'ONE WAY','position_m':[50,-9.5,2], 'governs_roadway_indices':[0]}]}
    (out/'scenario_geometry.json').write_text(json.dumps(geometry,indent=2)+'\n')
    with (out/'scenario_rule_evidence.jsonl').open('x') as stream:
      for row in mapping_rows:
        stream.write(json.dumps({'time_s':row['time_s'],'value':{'devices':[{'actor_id':220001,'native_name':'ONE WAY',
          'position_m':[50,-9.5,2], 'pixel_visibility_verified':False}]}})+'\n')
    finalize(out,out/'analysis-report.json')

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');parser.add_argument('--output-dir',default='.')
    parser.add_argument('--host',default='127.0.0.1');parser.add_argument('--port',type=int,default=2000)
    args=parser.parse_args()
    if args.check: print(json.dumps(check()))
    else: run(args)

"""Case-specific saved diagnostic measurements; physical sources require Native capture."""
import argparse,hashlib,json
from pathlib import Path
from worker_exchange.native_output import write_result

def required(root,name):
    path=root/name
    if not path.is_file():raise ValueError("Missing required source: "+name)
    return path

def sign_scope(p):
    s=p['direction_sign'];return {'native_id':s['native_id'],'text':s['text'],'orientation_deg':s['orientation_deg'],'governs_roadway_indices':s['governs_roadway_indices'],'original_frames':s['original_frames'],'one_way_lanes':p['one_way_lanes']}

def direction_projection(p):
    d=p['designated_direction_xy'];rows=p['velocity_rows'];return {'designated_direction_xy':d,'signed_projections_mps':[sum(a*b for a,b in zip(d,r['velocity_xy'])) for r in rows],'original_frames':[r['frame'] for r in rows]}

def finalize(root,output):
    source=required(root,"case_observation.json")
    p=json.loads(source.read_text())
    if p.get("law_id")!='NRS-484B-220-1':raise ValueError("Case observation law mismatch")
    h=hashlib.sha256(source.read_bytes()).hexdigest()
    measurements={}
    measurements['governing_direction_sign']={"method":'sign_scope',"value":sign_scope(p),"sources":{"case_observation.json":h}}
    measurements['actual_travel_direction']={"method":'direction_projection',"value":direction_projection(p),"sources":{"case_observation.json":h}}
    report={"format":"worker-analysis-report-v1","measurements":measurements,"limitations":["Diagnostic fixture only; Native motion, source packets, four-view pixels and legal acceptance remain unverified."]}
    output.write_text(json.dumps(report,indent=2)+"\n")
    cfg=json.loads(required(root,"config.json").read_text())
    rows=[json.loads(line) for line in required(root,"trace.jsonl").read_text().splitlines() if line]
    (root/"channels").mkdir(exist_ok=True)
    channel_values={
      "original_motion":lambda row:{"position_m":row["position_m"],"velocity_mps":row["velocity_mps"],"heading_deg":row["heading_deg"]},
      "native_geometry":lambda row:{"road_id":1,"one_way_lanes":p["one_way_lanes"]},
      "device_inventory":lambda row:p["direction_sign"],
      "view_provenance":lambda row:{"four_view_receipt":"four-view-receipt.json","pixel_visibility_verified":False}}
    for name,fn in channel_values.items():
      (root/"channels"/(name+".jsonl")).write_text(''.join(json.dumps({"time_s":row["time_s"],"value":fn(row)})+"\n" for row in rows))
    projection=measurements["actual_travel_direction"]["value"]["signed_projections_mps"]
    result={"case_id":cfg["selected_case_id"],"measured_values":{"signed_velocity_projection_mps":projection},
      "target_checks":[{"target":"designated_direction_projection","requested":cfg["case"]["variable_assignments"]["requested_speed_mps"]["value"],"measured":max(projection),
       "method":"maximum original velocity projection onto designated direction","tolerance":2,"matched":abs(max(projection)-cfg["case"]["variable_assignments"]["requested_speed_mps"]["value"])<=2,
       "physical_cause_confirmed":False,"cause_evidence":"trace.jsonl;case_observation.json"}],
      "setup_confirmed":False,"behavior_attempted":True,"maneuver_completed":False,
      "termination_reason":"saved diagnostic analysis; Native and pixel checks pending",
      "physical_failure_flags":{"detection_validated":False},"trace_reference":"trace.jsonl",
      "video_references":["raw.mkv"],"video_frame_map_reference":"video_frames.jsonl",
      "recording_description":cfg["case"]["recording_description"],
      "recording_evidence":[{"name":name,"unit":"structured record","reference":"channels/"+name+".jsonl"} for name in channel_values],
      "realized_observables":{}}
    write_result(root,result)
    return report

if __name__=="__main__":
    a=argparse.ArgumentParser();a.add_argument("--attempt",required=True);a.add_argument("--output",required=True);v=a.parse_args();finalize(Path(v.attempt),Path(v.output))

